import type { D1AuthoredBank } from '../corpus'

export const PESISIR_UTARA_D_R8: D1AuthoredBank = {
  universeId: 'pesisir-utara',
  rubricId: 'D-R8',
  STRONG: [
    { chapters: [
      { chapterNumber: 41, title: 'Tanggal Sidang Ditetapkan', paragraphs: ['Pemeriksa pusat menetapkan satu tanggal sidang untuk seluruh perkara jalur garam, dan sejak pengumuman itu Sari tahu ia hanya memiliki sembilan hari. Manifest asli kapal garam masih terselip pada rongga papan lantai kamarnya, lengkap dengan kolom awak yang dicoret. Menyerahkannya berarti membuka juga nama Latif sebagai orang yang mengikat karung atas perintah kantor izin.'] },
      { chapterNumber: 42, title: 'Latif Menawarkan Diri', paragraphs: ['Latif duduk di beranda dan berkata ia siap menanggung akibat apa pun asal kakaknya tidak lagi tidur dengan lampu menyala. Sari menjawab bahwa keputusan itu bukan milik adiknya sendiri. Keduanya berdebat sampai lonceng dermaga berbunyi, lalu berhenti tanpa kesepakatan. Malam itu manifest asli tetap terselip pada rongga papan, dan tidak seorang pun menyentuhnya.'] },
      { chapterNumber: 43, title: 'Damar Menawar Sunyi', paragraphs: ['Regent Damar mengirim surat tawaran melalui juru tulisnya: izin melaut Latif dipulihkan penuh, denda gudang dihapus, asalkan manifest asli tidak pernah muncul di ruang sidang. Surat itu diberi tanggal dan dicap lilin biru. Sari menyimpannya di sampul buku muatan tanpa menjawab, dan selama dua hari ia berhenti mencatat apa pun.'] },
      { chapterNumber: 44, title: 'Dua Naskah Keterangan', paragraphs: ['Sari menulis dua naskah keterangan di ruang catat pada malam yang sama. Naskah pertama menyebut seluruh isi manifest termasuk nama adiknya. Naskah kedua berhenti pada kolom berat dan membiarkan kolom awak tertutup. Ia meletakkan keduanya berdampingan di bawah lampu dan tidak sanggup memilih sampai minyak lampu itu hampir habis.'] },
      { chapterNumber: 45, title: 'Hasnah Menyerahkan Halaman', paragraphs: ['Bu Hasnah datang membawa halaman yang selama ini hilang dari buku muatan, halaman yang ia sobek sendiri tujuh tahun lalu demi melindungi anaknya. Perempuan tua itu berkata ia lelah menjadi orang yang menyimpan sobekan. Halaman tersebut mencantumkan tanggal yang sama dengan manifest asli, sehingga keduanya saling menguatkan bila diserahkan bersama.'] },
      { chapterNumber: 46, title: 'Ratih Bersedia Bersaksi', paragraphs: ['Nyi Ratih menyatakan bersedia bersaksi tentang orang kantor izin yang menghitung uang di meja belakang warungnya setiap malam kapal garam berangkat. Ia tahu warungnya akan menjadi sasaran pertama. Sari mencatat kesediaan itu di lembar terpisah dan meminta perempuan tersebut memikirkannya semalam lagi, tetapi Nyi Ratih menolak menunda jawabannya.'] },
      { chapterNumber: 47, title: 'Surat Bongkar Datang', paragraphs: ['Surat perintah pembongkaran warung dermaga tiba dua hari sebelum sidang, bertanggal mundur dan bercap kantor izin. Nyi Ratih membacanya di depan Sari lalu melipatnya menjadi empat. Tekanan itu jelas ditujukan kepada Sari, dan malam itu ia mengeluarkan surat tawaran Damar dari sampul buku muatan untuk pertama kalinya sejak menerimanya.'] },
      { chapterNumber: 48, title: 'Surat Tawaran Dibakar', paragraphs: ['Sari membakar surat tawaran itu di tungku dapur dan menunggu sampai cap lilin birunya meleleh habis. Latif menyaksikan dari pintu tanpa berkata apa pun. Sesudahnya Sari memasukkan manifest asli, halaman sobekan Bu Hasnah, dan lembar kesediaan Nyi Ratih ke dalam satu map bertali yang ia ikat dengan simpul ganda.'] },
      { chapterNumber: 49, title: 'Malam Sebelum Sidang', paragraphs: ['Pada malam terakhir Sari mengaku kepada Latif bahwa ia menyimpan manifest selama ini bukan demi keadilan melainkan karena takut kehilangan satu-satunya orang yang tersisa baginya. Ia berkata ketakutan itu justru membuatnya menjaga adiknya seperti barang bukti. Latif memeluknya dan berkata besok ia akan berdiri sendiri. Keduanya tidak tidur sampai pagi.'] },
      { chapterNumber: 50, title: 'Map Bertali Dibuka', paragraphs: ['Di ruang sidang Sari membuka map bertali itu dan membacakan seluruh isi manifest termasuk kolom awak yang memuat nama adiknya. Regent Damar kehilangan jabatan pada hari yang sama, dan Latif kehilangan izin melaut selama tiga tahun. Warung Nyi Ratih tetap dibongkar, lalu dibangun ulang dengan ganti rugi yang datang enam bulan kemudian. Sari menjadi pengawas muatan, dan setiap petang ia menjemput adiknya dari pasar es tempat lelaki itu kini bekerja.'] },
    ], justification: 'The runway builds the exact dilemma between the original manifest and Latif, and Bab 50 answers it with full disclosure plus aftermath that costs all three parties.' },
    { chapters: [
      { chapterNumber: 41, title: 'Sertifikat Uweng Dicabut', paragraphs: ['Sertifikat juru timbang Pak Uweng dicabut sepihak oleh kantor izin dengan alasan kelalaian, tepat setelah lelaki tua itu menolak menandatangani berat muatan malam. Sari menyaksikan bak penimbang lamanya disegel di depan gudang. Sejak hari tersebut seluruh angka berat di dermaga ditentukan oleh petugas baru yang tidak pernah menunjukkan alat ukur miliknya.'] },
      { chapterNumber: 42, title: 'Timbangan Kedua Disembunyikan', paragraphs: ['Pak Uweng mengaku ia masih menyimpan satu bak penimbang cadangan di rumahnya, alat yang ia kalibrasi sendiri setiap tahun. Sari memintanya menyerahkan alat itu kepada pemeriksa pusat, tetapi lelaki tua tersebut menolak karena rumahnya akan digeledah. Alat tersebut tetap tersimpan di bawah dipan, terbungkus kain sarung yang sudah lama tidak dicuci.'] },
      { chapterNumber: 43, title: 'Petugas Baru Menawar', paragraphs: ['Petugas timbang baru mendekati Sari dan menawarkan bagian dari selisih berat setiap kapal, dengan alasan semua juru catat sebelumnya menerima hal yang sama. Sari mendengarkan sampai selesai lalu menolak tanpa menaikkan suara. Petugas itu berkata penolakan tersebut akan diingat, dan sejak esok harinya lembar bongkar Sari selalu terlambat sampai ke kantor.'] },
      { chapterNumber: 44, title: 'Selisih Sembilan Kilogram', paragraphs: ['Sari menghitung sendiri satu kapal penuh memakai batu uji milik gudang dan menemukan selisih sembilan kilogram pada setiap peti besar. Angka itu ia salin ke dua lembar terpisah dan simpan di tempat berbeda. Ia menyadari bahwa tanpa alat bersertifikat, seluruh perhitungannya dapat dibantah oleh siapa pun di ruang sidang nanti.'] },
      { chapterNumber: 45, title: 'Anak Uweng Diancam', paragraphs: ['Kantor izin mengirim surat kepada sekolah di kota yang mempertanyakan asal biaya pendidikan anak Pak Uweng. Lelaki tua itu datang ke ruang catat dengan tangan gemetar dan meminta Sari berhenti menghitung. Sari tidak menjanjikan apa pun. Malam itu ia menuliskan nama anak tersebut pada lembar terakhir buku kecilnya sebagai orang yang harus dilindungi.'] },
      { chapterNumber: 46, title: 'Batu Uji Hilang', paragraphs: ['Batu uji milik gudang hilang dari lemari terkunci pada malam Jumat, dan penjaga malam berkata tidak melihat siapa pun masuk. Tanpa batu uji, perhitungan Sari kehilangan dasar pembanding. Bu Hasnah menyarankan memakai berat karung standar, tetapi Sari menolak karena angka itu tidak dapat dipertanggungjawabkan di depan pemeriksa pusat.'] },
      { chapterNumber: 47, title: 'Uweng Datang Malam', paragraphs: ['Pak Uweng datang ke ruang catat menjelang tengah malam membawa bungkusan kain sarung berisi bak penimbang cadangan beserta kartu kalibrasinya. Ia berkata anaknya sudah cukup besar untuk mengerti asal uang sekolahnya. Sari menerima alat itu dan menuliskan tanda terima bertanggal, lalu keduanya menandatangani lembar tersebut sebagai dua orang saksi.'] },
      { chapterNumber: 48, title: 'Alat Disegel Pemeriksa', paragraphs: ['Pemeriksa pusat menyegel bak penimbang cadangan itu sebagai barang bukti dan memerintahkan penimbangan ulang tiga peti besar di hadapan dua saksi. Hasilnya menunjukkan selisih sembilan kilogram persis seperti hitungan Sari. Petugas timbang baru meninggalkan dermaga pada sore yang sama tanpa mengambil barang-barangnya dari ruang jaga.'] },
      { chapterNumber: 49, title: 'Kartu Kalibrasi Dibaca', paragraphs: ['Malam sebelum sidang Sari membaca kartu kalibrasi itu dan menyadari Pak Uweng menandatanganinya setiap tahun selama tujuh tahun ia memilih diam. Ia berkata kepada lelaki tua tersebut bahwa selama ini ia menghakiminya karena lebih mudah daripada mengakui ia sendiri pernah menunda melapor demi adiknya. Keduanya duduk lama tanpa menambah kalimat apa pun.'] },
      { chapterNumber: 50, title: 'Sembilan Kilogram Dibacakan', paragraphs: ['Angka sembilan kilogram dibacakan di ruang sidang bersama kartu kalibrasi bertahun-tahun milik Pak Uweng, dan seluruh berat muatan jalur garam dinyatakan tidak sah. Lelaki tua itu dihukum denda dan kehilangan hak menimbang seumur hidup, sesuatu yang ia terima tanpa membantah. Anaknya pindah ke sekolah yang lebih murah di kota kecamatan. Sari mengambil alih meja timbang tersebut dan memasang kartu kalibrasi lama itu di dinding agar terlihat setiap hari.'] },
    ], justification: 'Every runway chapter narrows the evidentiary problem to a certified scale, and Bab 50 answers with the exact number while charging Uweng and his son a real price.' },
    { chapters: [
      { chapterNumber: 41, title: 'Ketukan Dari Peti', paragraphs: ['Saat mencatat muatan malam, Sari mendengar tiga ketukan teratur dari sebuah peti ikan asin yang disegel kantor izin. Berkasnya menyatakan peti itu berisi garam kering dan harus naik kapal sebelum fajar. Sari menahan derek selama sepuluh menit, tetapi petugas mengancam mencabut pekerjaannya bila segel dibuka tanpa surat pemeriksa.'] },
      { chapterNumber: 42, title: 'Garam Tidak Menjawab', paragraphs: ['Sari kembali ke gudang sebelum subuh dan mengetuk sisi peti dengan gagang pena. Tiga balasan terdengar dari dalam, lebih pelan daripada malam sebelumnya. Latif menawarkan linggis dari feri, tetapi membuka segel akan merusak bukti pengiriman resmi. Sari meminta adiknya menyembunyikan linggis itu di bawah tangga bongkar sambil ia mencari jalan yang sah.'] },
      { chapterNumber: 43, title: 'Surat Buka Ditolak', paragraphs: ['Permohonan membuka peti ditolak Regent Damar dengan alasan muatan sudah diperiksa. Penolakan tersebut ia tunjukkan kepada pemeriksa pusat; rombongan petugas kota baru dapat datang dua hari kemudian. Kapal dijadwalkan berangkat malam berikutnya. Dari balik dinding gudang, ketukan kini muncul hanya sekali setiap kali Sari memanggil orang di dalamnya.'] },
      { chapterNumber: 44, title: 'Hasnah Menahan Derek', paragraphs: ['Bu Hasnah memarkir gerobak garam melintang di depan derek agar peti tidak dapat dipindahkan. Kantor izin mendenda gudang untuk setiap jam keterlambatan. Sari berdiri bersama perempuan itu sambil menghitung waktu dan mendengar buruh mulai mengeluh. Menjelang petang, petugas menarik gerobak tersebut dan memasang penjaga di kedua pintu gudang.'] },
      { chapterNumber: 45, title: 'Udara Masuk Sedikit', paragraphs: ['Nyi Ratih menyelipkan batang bambu tipis melalui celah papan belakang gudang sampai menembus rongga peti, memberi sedikit udara tanpa mematahkan segel. Dari warungnya ia membawa air yang dialirkan lewat kain. Sari tahu pertolongan itu tidak cukup sampai pemeriksa tiba, sedangkan kapal sudah menyalakan lampu dan menunggu pasang malam.'] },
      { chapterNumber: 46, title: 'Kapal Menunggu Pasang', paragraphs: ['Regent Damar memerintahkan peti dipindahkan ketika air mulai naik, dan dua penjaga menyeret Bu Hasnah menjauh dari derek. Sari melihat bambu Nyi Ratih terlepas lalu mendengar satu ketukan terakhir. Ia mengambil linggis dari bawah tangga, tetapi Latif menahan tangannya dan bertanya apakah kakaknya siap kehilangan seluruh berkas yang masih melekat pada segel.'] },
      { chapterNumber: 47, title: 'Segel Atau Nyawa', paragraphs: ['Pemeriksa pusat mengirim pesan bahwa rombongannya tertahan di jalan pesisir sampai pagi. Sari diberi pilihan tertulis: pertahankan peti utuh sebagai bukti atau bertindak sendiri tanpa jaminan perkara dapat diteruskan. Ia membaca pesan itu di bawah lampu derek sementara tali pengangkat mulai menegang di atas peti yang diam.'] },
      { chapterNumber: 48, title: 'Linggis Masuk Celah', paragraphs: ['Sari menghentikan derek, memasukkan linggis ke celah tutup, dan mematahkan segel kantor izin di depan seluruh buruh malam. Di dalam peti terbaring dua awak muda dengan tangan terikat dan napas pendek. Latif memanggil tabib pelabuhan, sedangkan Sari mengumpulkan serpihan papan serta tali pengikat yang kini menjadi sisa bukti tanpa segel resmi.'] },
      { chapterNumber: 49, title: 'Dua Awak Bernapas', paragraphs: ['Kedua awak itu sadar menjelang malam berikutnya dan menyebut kapal garam tempat mereka dipaksa bekerja. Di hadapan Latif, Sari mengakui dirinya hampir membiarkan mereka berlayar demi menjaga berkas tetap sempurna, karena kertas terasa lebih mudah diselamatkan daripada manusia. Adiknya meletakkan linggis di antara mereka dan berkata pilihan itu sudah selesai dibuat.'] },
      { chapterNumber: 50, title: 'Peti Terbuka Bersaksi', paragraphs: ['Di ruang sidang, kedua awak memberikan keterangan dari kursi tabib sementara peti terbuka dipajang tanpa segel. Regent Damar menyebut barang itu rusak, tetapi para buruh malam menguatkan urutan pembukaannya. Ia dicopot dan jalur kapal garam dihentikan. Sari kehilangan jabatan juru catat karena melanggar tata muatan, lalu enam bulan berikutnya bekerja bersama Nyi Ratih mendata awak yang pulang melalui warung dermaga.'] },
    ], justification: 'The sealed crate, delayed inspector, blocked crane, bamboo airway, and hidden crowbar force Sari to choose two living crewmen over pristine evidence; the hearing and her lost job preserve that cost.' },
    { chapters: [
      { chapterNumber: 41, title: 'Tawaran Pindah Kota', paragraphs: ['Pemeriksa pusat menawari Sari pekerjaan tetap di kantor pelabuhan kota, jauh dari Tanjung Rembang dan dari orang-orang yang mengenalnya sejak kecil. Tawaran itu berlaku sampai sidang selesai. Ia menyimpan surat tawaran tersebut di dalam kaleng biskuit dan tidak memberitahukannya kepada Latif maupun kepada Nyi Ratih.'] },
      { chapterNumber: 42, title: 'Warung Jadi Markas', paragraphs: ['Meja belakang warung dermaga menjadi tempat Sari menyusun berkas setiap malam selama ruangan kerjanya belum boleh dipakai. Nyi Ratih menyediakan lampu dan kopi tanpa pernah menagih ongkos. Orang-orang mulai datang ke meja itu membawa keluhan tentang berat muatan, dan warung tersebut perlahan berubah menjadi tempat pengaduan tidak resmi di dermaga.'] },
      { chapterNumber: 43, title: 'Keluhan Ditulis Rapi', paragraphs: ['Sari menulis dua puluh tiga keluhan pedagang ke dalam satu buku bersampul kain dan memberi nomor pada setiap halaman. Setiap pengadu menandatangani sendiri baris miliknya. Buku itu disimpan di kolong lantai warung, tempat yang dulu ditawarkan Nyi Ratih ketika belum ada satu pun bukti yang perlu diamankan olehnya.'] },
      { chapterNumber: 44, title: 'Kantor Izin Menyegel', paragraphs: ['Kantor izin menyegel warung dermaga dengan alasan izin usaha kedaluwarsa, tepat pada hari buku keluhan mencapai halaman ketiga puluh. Nyi Ratih pindah berjualan di emperan gudang dengan meja lipat. Buku bersampul kain itu tertinggal di bawah papan lantai warung yang tersegel, tidak dapat diambil siapa pun tanpa merusak segel resmi.'] },
      { chapterNumber: 45, title: 'Segel Dijaga Petugas', paragraphs: ['Dua petugas dijaga bergantian di depan warung siang dan malam agar segel tidak dibuka. Sari mengamati dari kejauhan sambil menghitung jam pergantian mereka. Ia menolak usul Latif untuk masuk melalui atap karena bukti yang diambil dengan cara demikian akan kehilangan seluruh nilainya di hadapan pemeriksa pusat nanti.'] },
      { chapterNumber: 46, title: 'Permohonan Buka Segel', paragraphs: ['Sari mengajukan permohonan resmi pembukaan segel dengan alasan barang bukti perkara, dan permohonan itu ditolak dua kali oleh kantor izin. Pada permohonan ketiga ia menyertakan tanda tangan dua puluh tiga pengadu. Berkas tersebut diteruskan langsung kepada pemeriksa pusat tanpa melewati meja Regent Damar seperti dua permohonan sebelumnya.'] },
      { chapterNumber: 47, title: 'Segel Dibuka Resmi', paragraphs: ['Pemeriksa pusat membuka segel warung dengan berita acara dan mengambil buku bersampul kain dari kolong lantai di hadapan enam saksi. Nyi Ratih menangis di pintu ketika melihat lantainya dibongkar. Buku itu dibawa ke kota untuk diperiksa keasliannya, dan seluruh dua puluh tiga tanda tangan dinyatakan dapat dipertanggungjawabkan.'] },
      { chapterNumber: 48, title: 'Surat Tawaran Dibaca', paragraphs: ['Sari membuka kaleng biskuit dan membaca ulang surat tawaran kerja di kota yang tenggatnya jatuh pada hari sidang. Latif menemukan surat itu di meja dan bertanya sejak kapan kakaknya berencana pergi. Sari tidak menjawab, hanya melipat surat tersebut kembali dan meletakkannya di bawah lampu sampai pagi tiba.'] },
      { chapterNumber: 49, title: 'Alasan Ingin Pergi', paragraphs: ['Sari mengaku kepada Nyi Ratih bahwa ia ingin pergi bukan karena kota lebih baik, melainkan karena ia takut tinggal dan menyaksikan akibat dari setiap laporannya menimpa orang yang ia kenal namanya. Perempuan itu menjawab bahwa yang tinggal justru harus ikut membereskan. Sari menyimpan surat tawaran itu di saku sepanjang malam.'] },
      { chapterNumber: 50, title: 'Meja Lipat Emperan', paragraphs: ['Sari menolak tawaran kota di ruang sidang dan menyatakan diri sebagai pengadu bernomor dua puluh empat di dalam buku bersampul kain tersebut. Regent Damar dicopot, kantor izin dirombak, dan warung dermaga tetap tidak dapat dibangun kembali karena tanahnya milik pelabuhan. Nyi Ratih berjualan di emperan gudang selama dua tahun berikutnya. Sari menulis keluhan baru di meja lipat itu setiap malam, kini dengan nama dan jabatannya sendiri.'] },
    ], justification: 'The runway prepares the stay-or-leave choice through the sealed warung and the complaint book, and Bab 50 answers it with a refusal whose aftermath still leaves Ratih displaced.' },
    { chapters: [
      { chapterNumber: 41, title: 'Suara dari Karang', paragraphs: ['Latif mendengar peluit pendek dari gugusan karang setiap kali kapal garam melewati jalur terlarang tanpa pandu. Sari menunggu di pantai dan menemukan pantulan cahaya dari sebuah cermin kecil, bukan lampu resmi pelabuhan. Ia mencatat urutan peluit serta arah pantulannya, lalu menyadari seseorang di darat sedang menuntun kapal menghindari pos pemeriksaan.'] },
      { chapterNumber: 42, title: 'Cermin Terkubur Pasir', paragraphs: ['Saat air surut, Sari dan Latif menemukan cermin bertangkai kayu terkubur dekat karang, bersama bekas kaki menuju kebun kelapa. Tangkainya memuat tiga guratan yang juga dipakai buruh pelabuhan menandai regu malam. Sari tidak mengambilnya; ia menutup lokasi dengan jaring rusak agar benda tersebut dapat ditemukan pemeriksa dalam keadaan semula.'] },
      { chapterNumber: 43, title: 'Peluit Berubah Irama', paragraphs: ['Malam berikutnya irama peluit berubah setelah seseorang melihat jaring penanda Sari. Kapal membelok lebih jauh dan hampir menghantam karang sebelum cahaya cermin muncul dari titik baru. Latif ingin mengejar pemberi sinyal memakai perahu, tetapi Sari menahannya karena arus silang sedang kuat, sementara posisi mereka belum diketahui siapa pun di daratan.'] },
      { chapterNumber: 44, title: 'Peta Bunyi Dibuat', paragraphs: ['Sari meminta Nyi Ratih dan Pak Uweng berdiri di tiga titik pantai saat peluit berikutnya terdengar. Mereka menandai arah suara pada peta kasar, dan garisnya bertemu di gudang jaring milik kantor izin. Peta bunyi itu tidak mengenali pelaku, tetapi mempersempit lokasi darat tanpa bergantung pada cermin yang sudah dipindahkan.'] },
      { chapterNumber: 45, title: 'Gudang Jaring Terbakar', paragraphs: ['Gudang jaring terbakar sebelum pemeriksa pusat memperoleh surat penggeledahan. Di antara arang, Sari menemukan gulungan kawat tipis untuk menggantung cermin dan potongan daftar regu malam yang kehilangan bagian nama. Regent Damar menyebut kebakaran akibat puntung rokok, sedangkan penjaga gudang menghilang bersama keluarganya pada pagi yang sama.'] },
      { chapterNumber: 46, title: 'Latif Mengikuti Pantulan', paragraphs: ['Latif mengikuti pantulan baru memakai feri kosong tanpa persetujuan Sari. Dari laut ia melihat pemberi sinyal membawa peti dokumen ke perahu kecil, tetapi ombak membalikkan ferinya sebelum ia dapat mendekat. Latif selamat dengan luka pada bahu; peti serta perahu lolos menuju teluk utara sebelum kapal penjaga tiba.'] },
      { chapterNumber: 47, title: 'Bahu Dibalut Ratih', paragraphs: ['Nyi Ratih membalut bahu Latif di warung sambil Sari memarahinya karena bertindak sendiri. Latif menjawab bahwa kakaknya selalu menuntut orang lain berani, lalu menutup pintu ketika keberanian mereka tidak mengikuti rencananya. Sari tidak membalas. Ia menyimpan peta bunyi di bawah cangkir dan duduk sampai adiknya tertidur.'] },
      { chapterNumber: 48, title: 'Penjaga Gudang Kembali', paragraphs: ['Penjaga gudang kembali sendirian dan mengaku membunyikan peluit atas perintah juru tulis kantor izin, tetapi menolak menyebut nama di atas kertas karena keluarganya masih disembunyikan. Ia menunjukkan bekas luka bakar ketika menyelamatkan daftar regu. Sari meminta pemeriksa menempatkannya di rumah aman sebelum meminta keterangan resmi.'] },
      { chapterNumber: 49, title: 'Keberanian Bukan Miliknya', paragraphs: ['Sari meminta maaf kepada Latif karena memperlakukan keberanian adiknya sebagai sesuatu yang boleh ia nyalakan dan padamkan sesuai kebutuhan perkara. Ia mengaku ketakutan kehilangan keluarga membuatnya menyamakan perlindungan dengan kendali. Latif menerima permintaan maaf itu tanpa berjanji akan selalu patuh, lalu menyerahkan serpihan cermin yang tersangkut di bajunya saat feri terbalik.'] },
      { chapterNumber: 50, title: 'Peluit Terakhir Dibunyikan', paragraphs: ['Di sidang, penjaga gudang membunyikan pola peluit dan menjelaskan cara cermin mengarahkan kapal menjauhi pos pemeriksaan. Peta bunyi, kawat terbakar, dan serpihan dari baju Latif menguatkan keterangannya. Regent Damar dicopot, jalur karang ditutup, dan keluarga penjaga dipindahkan ke kota. Sari ikut Latif memasang pelampung peringatan; peluit lama mereka tenggelamkan di sisi karang tempat feri hampir merenggutnya.'] },
    ], justification: 'Whistles, mirror flashes, sound triangulation, a burned net shed, and Latif shipwreck prepare the hearing; the keeper demonstration closes the route while Sari relinquishes control over her brother courage.' },
  ],
  WEAK: [
    { chapters: [
      { chapterNumber: 41, title: 'Musim Bongkar Ramai', paragraphs: ['Musim bongkar tiba dan dermaga Tanjung Rembang dipenuhi kapal sejak subuh sampai petang. Sari mencatat muatan sepanjang hari tanpa sempat duduk lama. Latif bekerja di feri penyeberangan dan pulang menjelang tengah malam. Keduanya jarang bertemu selama pekan itu kecuali pada waktu sarapan di dapur belakang rumah.'] },
      { chapterNumber: 42, title: 'Gerobak Baru Datang', paragraphs: ['Empat gerobak muatan baru dikirim ke dermaga untuk menggantikan gerobak lama yang rodanya sering patah. Buruh angkut mencoba semuanya pada hari pertama dan menyebutnya jauh lebih ringan. Sari mencatat nomor setiap gerobak di buku inventaris gudang. Bu Hasnah meminta satu gerobak dipindahkan ke sisi gudang garam.'] },
      { chapterNumber: 43, title: 'Kopi Warung Naik', paragraphs: ['Harga kopi di warung Nyi Ratih naik sedikit karena pasokan dari kota terlambat dua pekan. Pelanggan tetap mengeluh tetapi tetap datang setiap sore. Sari membeli dua gelas seperti biasa dan duduk di meja dekat pintu. Percakapan hari itu berputar pada harga gula dan cuaca di jalur timur.'] },
      { chapterNumber: 44, title: 'Hujan Sepanjang Pekan', paragraphs: ['Hujan turun sepanjang pekan dan membuat lorong belakang gudang becek sampai ke pagar. Buruh memasang papan agar gerobak dapat lewat tanpa terperosok. Sari bekerja dengan sepatu basah selama enam hari berturut-turut. Pak Uweng menyediakan kain lap di dekat pintu ruang catat untuk siapa pun yang masuk.'] },
      { chapterNumber: 45, title: 'Feri Ganti Jadwal', paragraphs: ['Feri penyeberangan mengubah jadwal keberangkatan menjadi lebih pagi mengikuti perubahan arus pasang. Latif harus bangun sebelum subuh dan tidur lebih awal setiap malam. Sari menyesuaikan waktu masak agar adiknya tetap makan sebelum berangkat. Jadwal baru itu ditempel di papan pengumuman dermaga dalam dua bahasa.'] },
      { chapterNumber: 46, title: 'Karung Dijahit Ulang', paragraphs: ['Sejumlah karung garam yang jahitannya lepas dikumpulkan dan dijahit ulang oleh dua perempuan dari kampung sebelah. Bu Hasnah membayar mereka menurut jumlah karung. Sari mencatat jumlah karung yang diperbaiki di buku gudang. Pekerjaan itu selesai dalam tiga hari dan karung-karung tersebut kembali dipakai seperti biasa.'] },
      { chapterNumber: 47, title: 'Lampu Ruang Diganti', paragraphs: ['Lampu ruang catat diganti dengan yang lebih terang setelah bola lampu lama pecah terkena angin. Pak Uweng memasangnya memakai tangga kayu milik gudang. Sari membersihkan meja dari pecahan kaca dan melanjutkan pekerjaannya. Ruangan itu terasa berbeda selama beberapa hari sebelum semua orang terbiasa kembali.'] },
      { chapterNumber: 48, title: 'Perkara Dibuka Kota', paragraphs: ['Kabar datang bahwa kantor pusat di kota membuka pemeriksaan atas jalur garam berdasarkan laporan dari pihak lain yang tidak disebutkan namanya. Orang dermaga membicarakannya sepanjang sore di warung. Sari mendengar kabar itu dari Latif dan meneruskan pekerjaannya. Tidak ada yang meminta keterangan darinya pada pekan tersebut.'] },
      { chapterNumber: 49, title: 'Sarapan Seperti Biasa', paragraphs: ['Sari dan Latif sarapan di dapur belakang seperti hari kerja biasa sebelum keduanya berangkat. Mereka membicarakan harga minyak dan atap dapur yang perlu diperbaiki sebelum musim hujan berikutnya. Latif berangkat lebih dulu mengejar feri pagi. Sari mengunci pintu depan dan berjalan menuju dermaga membawa buku muatan.'] },
      { chapterNumber: 50, title: 'Kantor Izin Dirombak', paragraphs: ['Kantor izin pelabuhan dirombak oleh keputusan pusat dan Regent Damar dipindahkan ke daerah lain. Dermaga kembali bekerja seperti biasa pada pekan berikutnya. Sari tetap menjadi juru catat bongkar-muat dengan meja yang sama. Latif tetap bekerja di feri pagi, dan keduanya masih sarapan bersama sebelum berangkat setiap hari.'] },
    ], justification: 'The runway is ambient dermaga routine that prepares nothing, and Bab 50 stops at an off-screen administrative victory with no earned aftermath.' },
    { chapters: [
      { chapterNumber: 41, title: 'Latif Ingin Menikah', paragraphs: ['Latif menyampaikan niat menikah dengan perempuan dari kampung seberang pada akhir musim ini. Sari menanyakan kesiapan biaya dan tempat tinggal mereka nanti. Keduanya menghitung tabungan di meja dapur dan menyimpulkan masih kurang. Latif berkata ia akan menambah rute penyeberangan malam selama beberapa bulan ke depan.'] },
      { chapterNumber: 42, title: 'Keluarga Perempuan Datang', paragraphs: ['Keluarga perempuan itu datang ke rumah membawa kue dan membicarakan tanggal yang baik menurut hitungan pasang surut. Sari menyiapkan teh dan duduk mendengarkan sampai selesai. Percakapan berlangsung ramah dan berakhir dengan kesepakatan menunggu kabar berikutnya. Latif mengantar tamu sampai perempatan dekat pasar.'] },
      { chapterNumber: 43, title: 'Tabungan Dihitung Lagi', paragraphs: ['Tabungan dihitung ulang pada akhir bulan dan ternyata bertambah lebih cepat daripada perkiraan. Latif menyimpan uang itu di kaleng terpisah dengan tulisan pensil di tutupnya. Sari menyarankan menyimpannya di tempat lain, tetapi adiknya menolak. Keduanya membicarakan perahu yang perlu dicat sebelum acara berlangsung.'] },
      { chapterNumber: 44, title: 'Perahu Dicat Biru', paragraphs: ['Perahu Latif dicat biru muda dengan bantuan dua kawan seangkatannya di dermaga. Pekerjaan itu selesai dalam dua hari kerja penuh. Sari membelikan mereka makan siang sebagai ucapan terima kasih. Perahu tersebut kemudian dijemur di pantai selama sehari penuh sebelum kembali dilarungkan menjelang petang.'] },
      { chapterNumber: 45, title: 'Undangan Ditulis Tangan', paragraphs: ['Undangan ditulis tangan oleh Sari selama tiga malam berturut-turut karena percetakan di kota terlalu mahal. Latif membantu melipat dan memasukkannya ke dalam sampul. Keduanya membagi daftar nama menjadi dermaga, pasar, dan kampung seberang. Undangan tersebut mulai diantar pada hari Senin oleh dua anak tetangga.'] },
      { chapterNumber: 46, title: 'Tenda Dipesan Awal', paragraphs: ['Tenda dan kursi dipesan dari kecamatan sebulan sebelum tanggal acara agar tidak kehabisan. Pemilik tenda meminta uang muka setengah harga dan memberikan kuitansi. Sari menyimpan kuitansi itu di map bertali bersama daftar undangan. Bu Hasnah menawarkan halaman gudang sebagai tempat memasang tenda tersebut.'] },
      { chapterNumber: 47, title: 'Masakan Diatur Ratih', paragraphs: ['Nyi Ratih mengatur seluruh masakan untuk acara itu dan membuat daftar belanja sepanjang dua halaman. Ia meminta bantuan empat perempuan dari kampung sebelah. Sari menyerahkan uang belanja dan tidak ikut campur soal menu. Daftar tersebut ditempel di dinding dapur warung agar semua orang dapat membacanya.'] },
      { chapterNumber: 48, title: 'Perkara Selesai Kota', paragraphs: ['Perkara jalur garam dinyatakan selesai oleh kantor pusat berdasarkan pemeriksaan yang berjalan di kota selama beberapa bulan. Orang dermaga membicarakannya sebentar lalu kembali sibuk dengan persiapan acara. Sari mendengar kabar itu ketika sedang menghitung kursi. Ia melanjutkan pekerjaannya tanpa menanyakan rinciannya kepada siapa pun.'] },
      { chapterNumber: 49, title: 'Kursi Dihitung Ulang', paragraphs: ['Kursi dihitung ulang pada malam sebelum acara dan jumlahnya kurang dua belas dari daftar undangan. Latif meminjam sisanya dari balai kampung seberang memakai perahu. Sari menata meja bersama Nyi Ratih sampai larut. Keduanya pulang ketika tenda sudah berdiri penuh di halaman gudang garam.'] },
      { chapterNumber: 50, title: 'Acara Berjalan Lancar', paragraphs: ['Acara pernikahan Latif berjalan lancar di halaman gudang garam dengan tamu yang datang sejak pagi. Regent Damar sudah dipindahkan dan tidak seorang pun menyebut namanya sepanjang hari. Sari duduk di meja depan menerima tamu sampai sore. Malamnya tenda dibongkar dan dermaga kembali seperti biasa keesokan harinya.'] },
    ], justification: 'The runway prepares a wedding while the central conflict resolves off-screen; Bab 50 ends on a pleasant event answering no question the story raised.' },
    { chapters: [
      { chapterNumber: 41, title: 'Rak Arsip Dibersihkan', paragraphs: ['Sari mulai membersihkan rak arsip ruang catat yang sudah bertahun tidak disentuh siapa pun. Debu tebal menutupi berkas paling atas sampai tulisannya tidak terbaca. Ia mengerjakannya sedikit demi sedikit setiap selesai jam bongkar. Pak Uweng menyediakan kain dan ember air dari gudang perkakas sebelah.'] },
      { chapterNumber: 42, title: 'Berkas Lama Disusun', paragraphs: ['Berkas lama disusun menurut tahun dan diberi label kertas baru dengan tulisan tangan Sari. Beberapa berkas robek dan harus dijilid ulang memakai benang kasur. Pekerjaan itu memakan waktu lebih lama daripada perkiraan awalnya. Bu Hasnah sesekali datang melihat dan memuji kerapian susunan tersebut.'] },
      { chapterNumber: 43, title: 'Label Kertas Habis', paragraphs: ['Label kertas habis di tengah pekerjaan dan Sari harus membelinya di pasar pada hari Minggu. Penjual hanya memiliki warna kuning yang berbeda dari label sebelumnya. Ia tetap membelinya dan memakai warna campuran pada rak bagian bawah. Perbedaan warna itu tidak mengganggu urutan tahun sama sekali.'] },
      { chapterNumber: 44, title: 'Rak Bawah Rusak', paragraphs: ['Papan rak paling bawah patah karena beban berkas yang terlalu berat dan harus diganti. Tukang kayu memasang papan pengganti sepanjang hari. Selama perbaikan berlangsung, Sari memindahkan seluruh berkas ke lantai. Sesudahnya seluruh berkas dikembalikan menurut urutan yang sama seperti sebelum papan itu patah.'] },
      { chapterNumber: 45, title: 'Daftar Isi Dibuat', paragraphs: ['Sari membuat daftar isi arsip dalam satu buku terpisah agar berkas mudah dicari oleh siapa pun. Daftar itu memuat tahun, nomor rak, dan jumlah berkas pada setiap kelompok. Ia membuat salinan kedua, kemudian menitipkannya kepada Bu Hasnah. Pekerjaan tersebut selesai pada akhir bulan.'] },
      { chapterNumber: 46, title: 'Ruang Dicat Ulang', paragraphs: ['Dinding ruang catat dicat ulang dengan kapur putih setelah rak selesai dirapikan seluruhnya. Bau kapur bertahan selama tiga hari dan Sari bekerja dengan jendela terbuka. Pak Uweng membantu memindahkan meja ke tengah ruangan. Ruangan itu terlihat jauh lebih terang setelah pekerjaan pengecatan tersebut selesai.'] },
      { chapterNumber: 47, title: 'Kunci Lemari Diganti', paragraphs: ['Kunci lemari arsip diganti karena kunci lama sudah aus dan sering tersangkut. Tukang kunci dari pasar datang membawa dua anak kunci baru. Sari menyimpan satu di dompetnya dan menyerahkan satu kepada penjaga malam. Nomor kunci itu ia catat di buku jaga sesuai kebiasaan kantor.'] },
      { chapterNumber: 48, title: 'Pemeriksa Datang Kota', paragraphs: ['Pemeriksa dari kota datang membawa berkas hasil pemeriksaan jalur garam yang disusun tanpa keterlibatan orang dermaga. Mereka hanya meminjam ruang rapat pelabuhan selama satu hari. Sari melihat rombongan itu dari jendela ruang catat. Tidak seorang pun memanggilnya atau menanyakan isi arsip yang baru ia rapikan.'] },
      { chapterNumber: 49, title: 'Arsip Ditutup Rapi', paragraphs: ['Sari menutup pekerjaan arsipnya dengan menandatangani daftar isi dan memberi tanggal pada halaman terakhir. Ia mengunci lemari memakai kunci baru dan menyimpan anak kuncinya. Ruangan itu ditinggalkan dalam keadaan bersih dan tertata. Ia memadamkan lampu pukul enam lalu pulang berjalan kaki seperti biasa.'] },
      { chapterNumber: 50, title: 'Damar Dipindah Kota', paragraphs: ['Regent Damar dipindahkan ke kota lain berdasarkan keputusan pusat yang dibacakan di balai pelabuhan. Orang dermaga bertepuk tangan sebentar lalu bubar. Arsip yang dirapikan Sari selama berbulan tidak pernah dibuka dalam proses tersebut. Ia kembali ke ruang catat dan melanjutkan pencatatan muatan seperti hari-hari sebelumnya.'] },
    ], justification: 'Ten chapters of tidying prepare nothing; the resolution arrives from a city process and Bab 50 explicitly leaves the runway work unused.' },
    { chapters: [
      { chapterNumber: 41, title: 'Uweng Mulai Sakit', paragraphs: ['Pak Uweng mulai sering batuk dan tidak dapat berdiri lama di dekat bak penimbang. Sari menggantikannya mencatat berat pada beberapa hari dalam pekan itu. Lelaki tua tersebut berkata hanya masuk angin biasa. Bu Hasnah menyarankan ia beristirahat, tetapi ia tetap datang setiap pagi seperti biasanya.'] },
      { chapterNumber: 42, title: 'Obat Dibeli Pasar', paragraphs: ['Sari membeli obat batuk di pasar pagi dan menyerahkannya kepada Pak Uweng di gudang. Lelaki tua itu berterima kasih dan meminumnya di depan Sari. Batuknya berkurang selama beberapa hari lalu kembali seperti semula. Ia tetap menolak pergi ke puskesmas kecamatan meski sudah diantar tawaran perahu.'] },
      { chapterNumber: 43, title: 'Puskesmas Akhirnya Didatangi', paragraphs: ['Pak Uweng akhirnya bersedia ke puskesmas kecamatan setelah didesak Bu Hasnah selama beberapa hari. Petugas di sana memberikan obat lain dan menyarankan istirahat dua pekan. Sari mengantarnya pulang dengan perahu sore. Lelaki tua itu menyimpan resepnya di dompet dan berkata akan menebusnya nanti.'] },
      { chapterNumber: 44, title: 'Bak Penimbang Kosong', paragraphs: ['Bak penimbang kosong selama dua pekan karena Pak Uweng beristirahat sesuai anjuran petugas puskesmas. Kantor pelabuhan mengirim petugas pengganti sementara dari dermaga sebelah. Sari bekerja seperti biasa mendampingi petugas tersebut. Angka berat tetap tercatat dan tidak ada perbedaan berarti selama masa penggantian itu.'] },
      { chapterNumber: 45, title: 'Uweng Kembali Bekerja', paragraphs: ['Pak Uweng kembali bekerja setelah dua pekan dan terlihat lebih segar daripada sebelumnya. Ia membawa kue dari kampungnya untuk seisi gudang sebagai ucapan terima kasih. Sari menyimpan sepotong untuk Latif di rumah. Hari itu berjalan seperti hari kerja biasa tanpa kejadian yang perlu dicatat.'] },
      { chapterNumber: 46, title: 'Batuk Datang Lagi', paragraphs: ['Batuk Pak Uweng kembali pada pekan berikutnya dan kali ini disertai demam ringan pada malam hari. Ia tetap datang bekerja tetapi duduk lebih sering daripada biasanya. Sari menyiapkan kursi di dekat bak penimbang untuknya. Bu Hasnah membawakan air jahe hangat setiap pagi selama pekan tersebut.'] },
      { chapterNumber: 47, title: 'Anak Uweng Datang', paragraphs: ['Anak Pak Uweng datang dari kota selama tiga hari untuk menengok ayahnya. Ia membawa obat dari apotek yang lebih lengkap dan berbicara panjang dengan Bu Hasnah. Sari bertemu dengannya sekali di gudang dan bertukar sapa singkat. Anak itu kembali ke kota pada hari Minggu pagi.'] },
      { chapterNumber: 48, title: 'Kabar Pemeriksaan Sampai', paragraphs: ['Kabar bahwa pemeriksaan jalur garam sudah selesai di kota sampai ke dermaga melalui awak feri. Orang-orang membicarakannya di warung sepanjang sore. Sari mendengarkan tanpa ikut berkomentar karena sedang mengurus jadwal timbang. Pak Uweng berkata syukurlah, lalu melanjutkan pekerjaannya sampai lonceng berbunyi.'] },
      { chapterNumber: 49, title: 'Jadwal Timbang Disusun', paragraphs: ['Sari menyusun jadwal timbang bulan berikutnya dengan memberi Pak Uweng hari kerja yang lebih sedikit. Lelaki tua itu menyetujuinya tanpa keberatan sama sekali. Jadwal tersebut ditempel di papan gudang pada sore hari. Keduanya menutup gudang bersama dan pulang ke arah yang berlawanan seperti biasa.'] },
      { chapterNumber: 50, title: 'Timbangan Baru Datang', paragraphs: ['Bak penimbang baru bersertifikat dikirim kantor pusat setelah kantor izin dirombak, dan Pak Uweng ditugaskan mengajari petugas muda memakainya. Regent Damar sudah tidak berada di pelabuhan sejak pekan sebelumnya. Sari mencatat kedatangan alat itu di buku inventaris. Dermaga bekerja seperti biasa pada hari berikutnya.'] },
    ], justification: 'The runway follows an illness subplot with no bearing on the conflict, and Bab 50 delivers equipment news instead of answering anything prepared.' },
    { chapters: [
      { chapterNumber: 41, title: 'Jalur Timur Ditutup', paragraphs: ['Jalur pelayaran timur ditutup sementara karena karang yang bergeser setelah badai bulan lalu. Kapal garam dialihkan melewati jalur utara yang lebih panjang dua jam. Sari menyesuaikan jam pencatatan mengikuti kedatangan baru tersebut. Buruh angkut mengeluh karena harus bekerja lebih malam daripada kebiasaan mereka.'] },
      { chapterNumber: 42, title: 'Peta Karang Diperbarui', paragraphs: ['Petugas dari kota datang memperbarui peta karang jalur timur memakai perahu ukur selama tiga hari. Latif ikut membantu sebagai penunjuk arah karena hafal perairan itu. Sari mencatat jadwal keberangkatan perahu ukur di buku jaga. Hasil pengukuran akan dikirim ke kantor pelabuhan pada bulan berikutnya.'] },
      { chapterNumber: 43, title: 'Jalur Utara Padat', paragraphs: ['Jalur utara menjadi padat karena seluruh kapal dialihkan ke sana selama penutupan berlangsung. Antrean sandar memanjang sampai ke luar kolam pelabuhan setiap sore. Sari mencatat waktu tunggu setiap kapal untuk laporan bulanan. Kantor pelabuhan menambah satu petugas pandu selama masa padat tersebut.'] },
      { chapterNumber: 44, title: 'Pelampung Tanda Dipasang', paragraphs: ['Pelampung bertanda dipasang di sepanjang jalur utara agar nakhoda tidak keluar dari alur aman. Pemasangan dilakukan oleh dua perahu kerja dalam waktu satu pekan. Latif ikut sekali sebagai tenaga tambahan dan pulang dengan tangan penuh cat. Sari mencuci pakaian kerjanya dua kali pada malam itu.'] },
      { chapterNumber: 45, title: 'Antrean Mulai Berkurang', paragraphs: ['Antrean sandar mulai berkurang setelah pelampung terpasang dan nakhoda terbiasa dengan alur baru. Waktu tunggu turun hampir setengah dibanding pekan sebelumnya. Sari mencatat penurunan itu dalam laporan bulanan gudang. Buruh angkut kembali bekerja pada jam biasa dan berhenti mengeluh tentang lembur malam.'] },
      { chapterNumber: 46, title: 'Karang Selesai Diukur', paragraphs: ['Pengukuran karang jalur timur selesai dan hasilnya menyatakan alur dapat dibuka kembali dengan pergeseran sedikit ke utara. Kantor pelabuhan mengumumkan pembukaan pada awal bulan berikutnya. Nakhoda menyambutnya dengan lega di warung dermaga. Sari menyiapkan format pencatatan baru mengikuti jam kedatangan yang akan berubah lagi.'] },
      { chapterNumber: 47, title: 'Jalur Timur Dibuka', paragraphs: ['Jalur timur dibuka kembali dan kapal pertama melewatinya pada pagi berkabut tanpa hambatan apa pun. Latif berada di feri yang menyeberang beriringan dengan kapal tersebut. Sari mencatat kedatangan pertama itu dengan tinta biru di buku muatan. Dermaga kembali ke jam kerja seperti sebelum badai bulan lalu.'] },
      { chapterNumber: 48, title: 'Laporan Bulanan Dikirim', paragraphs: ['Laporan bulanan berisi waktu tunggu, jumlah kapal, dan berat muatan dikirim ke kantor pelabuhan tepat waktu. Bu Hasnah menandatanganinya sebagai pengurus gudang. Sari menyimpan salinannya di map bertali. Kabar bahwa perkara jalur garam sedang diperiksa di kota beredar lagi pada hari yang sama.'] },
      { chapterNumber: 49, title: 'Format Baru Dipakai', paragraphs: ['Format pencatatan baru mulai dipakai penuh dan terbukti lebih cepat daripada format lama. Sari mengajari dua juru catat muda cara mengisinya selama satu sore. Keduanya mencobanya pada kapal terakhir hari itu tanpa kesalahan. Ruang catat ditutup pukul tujuh dan lampunya dipadamkan seperti biasa.'] },
      { chapterNumber: 50, title: 'Kabar Damar Dicopot', paragraphs: ['Kabar bahwa Regent Damar dicopot sampai ke dermaga melalui surat edaran pusat pada hari Rabu pagi. Orang-orang membacanya di papan pengumuman lalu kembali bekerja. Jalur timur tetap berjalan lancar dan format pencatatan baru tetap dipakai. Sari melanjutkan pekerjaannya pada kapal siang tanpa perubahan apa pun pada mejanya.'] },
    ], justification: 'The runway is a navigation logistics arc, and the antagonist falls in a bulletin at Bab 50 with no connection to anything prepared.' },
  ],
  BORDERLINE: [
    { chapters: [
      { chapterNumber: 41, title: 'Garis Air Berubah', paragraphs: ['Sari melihat garis air pada tiang pintu pasang lebih tinggi daripada angka yang ditulis penjaga. Selisih itu membuat kapal garam tercatat berangkat ketika alur seharusnya tertutup. Ia menggores tanda kecil pada tiang menggunakan paku, lalu menyalin tinggi sebenarnya ke buku muatan sebelum air surut menghapus jejak lumpurnya.'] },
      { chapterNumber: 42, title: 'Tiang Dicat Putih', paragraphs: ['Keesokan pagi seluruh tiang pintu pasang dicat putih oleh pekerja kantor izin, menutup goresan Sari dan garis lumpur lama. Penjaga mengaku pengecatan sudah dijadwalkan berminggu-minggu. Sari memungut serpihan cat basah dari tanah, tetapi benda itu tidak membuktikan tinggi air yang dilihatnya pada malam sebelumnya.'] },
      { chapterNumber: 43, title: 'Ratih Mengingat Banjir', paragraphs: ['Nyi Ratih mengingat lantai warungnya terendam pada setiap tanggal kapal tercatat berangkat ketika air rendah. Ia menunjukkan bekas asin pada kaki meja dan daftar belanja yang tintanya luntur. Sari menyadari bekas banjir dapat menguatkan catatannya, tetapi meja tersebut telah dipindahkan beberapa kali dan tidak memiliki penanda tanggal.'] },
      { chapterNumber: 44, title: 'Pasang Dicatat Sendiri', paragraphs: ['Selama enam malam Sari mengukur tinggi air dengan tali berikat batu dari jembatan kecil, lalu mencatat waktu lonceng serta posisi simpul basah. Angkanya selalu berbeda dari buku penjaga ketika kapal garam lewat. Ia menyimpan tali tersebut pada paku warung, meski panjangnya dapat berubah setiap kali serat terkena air laut.'] },
      { chapterNumber: 45, title: 'Pintu Air Ditutup', paragraphs: ['Kantor izin menutup akses ke jembatan kecil dan memasang papan larangan mengukur aliran tanpa izin. Sari terpaksa mengamati dari warung, terlalu jauh untuk membaca garis tiang. Nyi Ratih memindahkan meja bekas banjir ke dekat pintu agar noda asinnya terlihat oleh pemeriksa yang dijadwalkan datang.'] },
      { chapterNumber: 46, title: 'Meja Tersapu Pasang', paragraphs: ['Pasang besar menerjang warung pada malam berikutnya dan menghanyutkan meja bernoda sebelum pemeriksa tiba. Nyi Ratih menemukan satu kakinya tersangkut di tali tambat, sedangkan tiga kaki lain hilang. Bekas asin lama bercampur noda baru, sehingga urutan banjir tidak lagi dapat dibedakan melalui kayu tersebut.'] },
      { chapterNumber: 47, title: 'Penjaga Membawa Buku', paragraphs: ['Penjaga pintu pasang datang diam-diam membawa buku catatan pribadinya yang memuat tinggi air sebenarnya, berbeda dari angka resmi yang dipaksakan kantor izin. Ia bersedia menyerahkan salinan, tetapi menolak hadir di sidang karena anaknya bekerja sebagai petugas gerbang. Sari menerima buku itu tanpa memperoleh janji kesaksian.'] },
      { chapterNumber: 48, title: 'Dua Catatan Beradu', paragraphs: ['Pemeriksa pusat mencocokkan buku pribadi penjaga dengan enam ukuran tali milik Sari dan menemukan waktu pasang yang serupa. Angka resmi kantor izin tetap dianggap sah karena penjaga belum bersedia mengaku. Sari diberi satu malam untuk membawa saksi tersebut atau membiarkan persoalan tinggi air menjadi lampiran kecil saja.'] },
      { chapterNumber: 49, title: 'Paku di Tiang', paragraphs: ['Sari menemui penjaga dan berkata ia memahami pilihan melindungi keluarga karena pernah melakukan hal serupa untuk Latif. Lelaki itu tidak menjawab apakah akan datang. Sebelum pulang, ia memberi tahu bahwa cat putih pada tiang mulai mengelupas dan goresan paku mungkin terlihat lagi setelah satu kali pasang besar.'] },
      { chapterNumber: 50, title: 'Goresan Muncul Kembali', paragraphs: ['Cat putih mengelupas pagi sidang dan goresan paku tampak pada tinggi yang cocok dengan buku pribadi penjaga. Pemeriksa menerima foto tiang serta ukuran tali sebagai bukti pendukung, tetapi Regent Damar dicopot terutama karena manifest dari perkara lain. Penjaga tidak pernah muncul, angka resmi diperbaiki, dan Sari tetap tidak tahu apakah kapal-kapal lama dapat dituntut berdasarkan garis yang nyaris hilang itu.'] },
    ], justification: 'The altered tide marks, painted post, flooded table, wet rope, private log, and reappearing nail scratch support the accusation, but Bab 50 leaves the witness absent and the old departures unresolved.' },
    { chapters: [
      { chapterNumber: 41, title: 'Karcis Nomor Ganjil', paragraphs: ['Sari mengumpulkan karcis feri dengan nomor ganjil yang tercecer di dek selama musim bongkar. Nomor tersebut tidak pernah muncul pada daftar keberangkatan resmi mana pun. Latif berkata karcis ganjil biasanya dipakai untuk penumpang yang naik di luar dermaga utama, sesuatu yang seharusnya tidak dilakukan siapa pun.'] },
      { chapterNumber: 42, title: 'Titik Naik Rahasia', paragraphs: ['Latif menunjukkan titik naik di balik tanjung tempat perahu kecil merapat pada malam tertentu tanpa lampu. Sari mengamati dari kejauhan selama dua malam dan menghitung jumlah orang yang naik. Angka itu cocok dengan jumlah karcis ganjil yang ia kumpulkan selama pekan yang sama di dek feri.'] },
      { chapterNumber: 43, title: 'Daftar Penumpang Kosong', paragraphs: ['Daftar penumpang feri untuk malam-malam tersebut tercatat kosong pada arsip kantor pelabuhan. Sari menyalin ketiga halaman kosong itu sebagai bukti ketidaksesuaian. Petugas arsip menanyakan keperluannya dan ia menjawab untuk laporan gudang. Salinan tersebut ia titipkan bersama karcis ganjil dalam wadah gula milik Nyi Ratih.'] },
      { chapterNumber: 44, title: 'Perahu Kecil Ditandai', paragraphs: ['Sari menandai perahu kecil itu dengan mencatat bentuk lambungnya dan cat yang mengelupas pada haluan. Latif mengenalinya sebagai perahu milik seorang pengumpul ikan dari kampung seberang. Nama pemiliknya diketahui, tetapi tidak seorang pun bersedia menyebutnya secara tertulis kepada Sari pada pekan tersebut.'] },
      { chapterNumber: 45, title: 'Pemilik Perahu Menghilang', paragraphs: ['Pemilik perahu itu tidak lagi terlihat di kampung seberang sejak Sari mulai menanyakan namanya kepada orang pasar. Rumahnya kosong dan perahunya ditarik ke darat. Latif menyarankan berhenti bertanya karena orang mulai memperhatikan mereka. Sari menuruti saran itu selama beberapa hari lalu melanjutkan diam-diam.'] },
      { chapterNumber: 46, title: 'Karcis Cocok Tanggal', paragraphs: ['Sari mencocokkan tanggal pada karcis ganjil dengan tanggal keberangkatan kapal garam dan seluruhnya berpasangan tanpa kecuali. Pola itu menunjukkan orang dinaikkan ke feri lalu dipindahkan ke kapal di luar pelabuhan. Ia menuliskan kesimpulan tersebut dalam satu halaman dan menyimpannya bersama karcis di kaleng gula.'] },
      { chapterNumber: 47, title: 'Pemeriksa Menerima Salinan', paragraphs: ['Pemeriksa pusat menerima salinan karcis dan halaman daftar kosong itu sebagai lampiran keterangan Sari. Ia meminta bukti tambahan berupa keterangan penumpang dari lokasi naik rahasia tersebut. Sari menjawab belum memilikinya. Pemeriksa mencatat lampiran itu sebagai bukti pendukung, bukan bukti utama, dalam berkas perkara.'] },
      { chapterNumber: 48, title: 'Saksi Tidak Ditemukan', paragraphs: ['Selama dua hari penuh Sari mencari bekas penumpang dari balik tanjung, tetapi pulang tanpa hasil. Setiap orang yang ditanya menolak berbicara atau mengaku tidak tahu. Ia kembali ke rumah dengan tangan kosong pada malam sebelum sidang. Kaleng gula itu tetap berisi karcis dan salinan halaman kosong.'] },
      { chapterNumber: 49, title: 'Menghitung Tanpa Saksi', paragraphs: ['Di hadapan Nyi Ratih, Sari mengakui bahwa ia selalu lebih percaya angka daripada orang karena angka tidak pernah menghilang seperti ayahnya dulu. Ia berkata kini angka-angkanya justru tidak cukup. Perempuan itu menuangkan kopi dan berkata mungkin sudah waktunya belajar meminta. Sari mengangguk lalu pulang menjelang tengah malam.'] },
      { chapterNumber: 50, title: 'Karcis Diterima Bukti', paragraphs: ['Pemeriksa pusat menerima karcis ganjil sebagai bukti pendukung dan Regent Damar dinyatakan bersalah terutama berdasarkan berkas berat muatan dari pihak lain. Perkara pengangkutan orang tetap dibuka tetapi belum memiliki saksi. Sari kembali ke dermaga dan meneruskan pencarian sendirian, sementara kaleng gula itu kini disimpan di kantor pemeriksa pusat di kota.'] },
    ], justification: 'Bab 50 does answer the runway question, yet the victory rests on someone else evidence and the prepared thread closes only partially.' },
    { chapters: [
      { chapterNumber: 41, title: 'Lonceng Berbunyi Ganda', paragraphs: ['Lonceng bongkar berbunyi dua kali pada tengah malam, tanda yang seharusnya hanya dipakai saat orang jatuh ke air. Tidak ada penyelamatan terjadi, tetapi satu kapal garam segera meninggalkan dermaga tanpa pemeriksaan. Sari mencatat bunyi itu pada pinggir buku muatan dan bertanya siapa yang memegang tali lonceng malam tersebut.'] },
      { chapterNumber: 42, title: 'Tali Lonceng Dipotong', paragraphs: ['Tali lonceng ditemukan terpotong pendek keesokan pagi sehingga hanya dapat ditarik dari loteng gudang. Bu Hasnah membuka loteng dan menemukan jejak lumpur menuju lubang angin. Sari mengukur bekas telapak dengan seutas tali, tetapi hujan siang menghapus jejak sebelum pemeriksa pusat sempat melihatnya.'] },
      { chapterNumber: 43, title: 'Bunyi Kedua Terulang', paragraphs: ['Dua malam kemudian lonceng kembali berbunyi ganda dan kapal lain berangkat tanpa timbang. Sari berjaga di dekat loteng, namun orang yang menariknya lolos melalui atap warung. Nyi Ratih melihat bayangan membawa mantel petugas pelabuhan, tetapi wajahnya tertutup tudung dan ukuran tubuhnya tidak dapat dikenali.'] },
      { chapterNumber: 44, title: 'Daftar Mantel Diperiksa', paragraphs: ['Daftar perlengkapan menunjukkan enam mantel serupa dibagikan kepada petugas kantor izin. Sari mencatat nama penerimanya, lalu mengetahui dua mantel dilaporkan hilang sebelum bunyi pertama. Daftar itu mempersempit orang yang mungkin terlibat tetapi belum menunjuk siapa pun, sebab mantel dapat berpindah tangan tanpa catatan.'] },
      { chapterNumber: 45, title: 'Latif Mendengar Kode', paragraphs: ['Latif mendengar awak kapal menyebut bunyi ganda sebagai tanda bahwa pemeriksaan sudah dibayar. Ia menawarkan diri mengikuti kapal berikutnya untuk mencari pemberi kode. Sari melarangnya naik karena khawatir adiknya tidak kembali. Latif menuduh kakaknya lebih memilih perkara menggantung daripada membiarkan orang lain mengambil risiko sendiri.'] },
      { chapterNumber: 46, title: 'Lonceng Dijaga Bergilir', paragraphs: ['Bu Hasnah mengatur buruh gudang menjaga lonceng secara bergilir, dan dua malam berlalu tanpa bunyi ganda. Pada malam ketiga seorang penjaga dipukul dari belakang dan tali baru ditarik. Pelaku meninggalkan kancing kuningan bercap kantor pelabuhan, benda umum yang dipakai puluhan pegawai dan tidak cukup untuk mengenali pemiliknya.'] },
      { chapterNumber: 47, title: 'Kancing Dibawa Pemeriksa', paragraphs: ['Pemeriksa pusat menerima kancing, daftar mantel, serta catatan waktu Sari sebagai bukti pendukung. Ia meminta seseorang mengikuti kapal berikutnya agar pemberi kode dapat dikenali. Latif mengulangi tawarannya di depan pemeriksa, membuat larangan kakaknya tidak lagi menentukan. Keberangkatan berikut dijadwalkan tepat pada malam sebelum sidang.'] },
      { chapterNumber: 48, title: 'Latif Naik Diam-Diam', paragraphs: ['Latif menyelinap ke kapal garam melalui peti kosong tanpa memberi tahu Sari. Dari geladak ia melihat juru tulis Regent Damar menyerahkan uang kepada awak setelah lonceng berbunyi. Ia kembali dengan karcis upah yang ditandatangani juru tulis, tetapi tidak membawa saksi lain karena seluruh awak menolak turun bersamanya.'] },
      { chapterNumber: 49, title: 'Larangan Kakak Retak', paragraphs: ['Sari memarahi Latif karena mempertaruhkan nyawa, lalu mengakui bahwa larangannya lahir dari ketakutan ditinggalkan, bukan penilaian atas kemampuan adiknya. Latif menjawab ia tidak meminta izin untuk menjadi orang dewasa. Keduanya menyimpan karcis upah dalam kotak kayu, tetapi pertengkaran mereka berhenti sebelum Sari meminta maaf.'] },
      { chapterNumber: 50, title: 'Karcis Upah Ditolak', paragraphs: ['Karcis upah menghubungkan juru tulis dengan kapal, tetapi pemeriksa menolak menjadikannya bukti utama tanpa saksi atau catatan pembayaran pembanding. Regent Damar tetap dicopot berdasarkan manifest lain, sedangkan perkara lonceng ditunda. Latif menerima pekerjaan di kapal kota dan pergi sebulan kemudian; Sari mengantarnya sampai feri tanpa pernah menyelesaikan kalimat maaf yang tertahan malam itu.'] },
    ], justification: 'The alarm code, cut rope, muddy roof, borrowed coats, brass button, and Latif hidden voyage build a plausible thread, but Bab 50 rejects its key ticket and leaves both the bribery and sibling apology unfinished.' },
  ],
}
